// Checks that every internal link in the built site (website/dist) points at a page or file
// that exists, including links rewritten by sync-docs and generated by TypeDoc. Run after
// `pnpm docs:build`; the Docs workflow does.
import { existsSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { listFiles, websiteDir } from '../src/lib/pages';

const dist = join(websiteDir, 'dist');
if (!existsSync(dist)) {
  console.error('check-links: website/dist does not exist. Run `pnpm docs:build` first.');
  process.exit(1);
}

function exists(pathname: string): boolean {
  const clean = decodeURIComponent(pathname).replace(/\/+$/, '');
  return [clean, `${clean}/index.html`, `${clean}.html`].some((p) => existsSync(join(dist, p)));
}

let broken = 0;
const pages = listFiles(dist, ['.html']);
for (const page of pages) {
  const html = readFileSync(page, 'utf8');
  for (const match of html.matchAll(/\s(?:href|src)="(\/[^"#?]*)[^"]*"/g)) {
    const target = match[1] ?? '';
    if (target.startsWith('//') || exists(target)) continue;
    broken++;
    console.error(`${relative(dist, page)}: broken link ${target}`);
  }
}
if (broken > 0) {
  console.error(`\ncheck-links: ${String(broken)} broken link(s).`);
  process.exit(1);
}
console.log(`check-links: OK. ${String(pages.length)} pages.`);
